import java.util.Arrays;
import java.util.Comparator;
import java.util.Scanner;

public class Main {
    static class Abc {
        int a;
        int b;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        Abc[] ar = new Abc[8];
        for (int i = 0; i < 8; i++) {
            ar[i] = new Abc();
            ar[i].a = scanner.nextInt();
            ar[i].b = scanner.nextInt();
        }

        Arrays.sort(ar, Comparator.comparingInt(o -> o.a));

        if (ar[0].a != ar[1].a || ar[0].a != ar[2].a) {
            System.out.println("ugly");
        } else if (ar[5].a != ar[6].a || ar[5].a != ar[7].a) {
            System.out.println("ugly");
        } else if (ar[3].a != ar[4].a) {
            System.out.println("ugly");
        } else if (ar[0].a == ar[7].a) {
            System.out.println("ugly");
        } else if (ar[0].a == ar[3].a) {
            System.out.println("ugly");
        } else {
            int x = ar[0].b;
            int y = ar[1].b;
            int z = ar[2].b;
            if (x == y || x == z) {
                System.out.println("ugly");
            } else {
                int min = 10000000;
                int max = -1;
                int loopY = 0;
                for (x = 5; x < 8; x++) {
                    if (ar[x].b < min) min = ar[x].b;
                    if (ar[x].b > max) max = ar[x].b;
                    for (loopY = 0; loopY <= 2; loopY++) {
                        if (ar[x].b == ar[loopY].b) break;
                    }
                    if (loopY == 3) break;
                }
                if (loopY == 3) {
                    System.out.println("ugly");
                } else {
                    x = ar[5].b;
                    y = ar[6].b;
                    z = ar[7].b;
                    if (x == y || x == z) {
                        System.out.println("ugly");
                    } else if (!(ar[3].b == min || ar[3].b == max)) {
                        System.out.println("ugly");
                    } else if (!(ar[4].b == min || ar[4].b == max)) {
                        System.out.println("ugly");
                    } else if (ar[3].b == ar[4].b) {
                        System.out.println("ugly");
                    } else {
                        System.out.println("respectable");
                    }
                }
            }
        }
        scanner.close();
    }
}

import java.util.*;

public class Main {
    static class Point {
        int a;
        int b;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        Point[] ar = new Point[8];
        for (int i = 0; i < 8; i++) {
            ar[i] = new Point();
            ar[i].a = scanner.nextInt();
            ar[i].b = scanner.nextInt();
        }

        Arrays.sort(ar, Comparator.comparingInt(p -> p.a));

        if (ar[0].a != ar[1].a || ar[0].a != ar[2].a) {
            System.out.println("ugly");
            return;
        }
        if (ar[5].a != ar[6].a || ar[5].a != ar[7].a) {
            System.out.println("ugly");
            return;
        }
        if (ar[3].a != ar[4].a) {
            System.out.println("ugly");
            return;
        }
        if (ar[0].a == ar[7].a) {
            System.out.println("ugly");
            return;
        }
        if (ar[0].a == ar[3].a) {
            System.out.println("ugly");
            return;
        }

        int x = ar[0].b, y = ar[1].b, z = ar[2].b;
        if (x == y || x == z) {
            System.out.println("ugly");
            return;
        }

        int min = 10000000;
        int max = -1;
        boolean ugly = false;
        for (int i = 5; i < 8; i++) {
            if (ar[i].b < min) min = ar[i].b;
            if (ar[i].b > max) max = ar[i].b;
            boolean match = false;
            for (int j = 0; j <= 2; j++) {
                if (ar[i].b == ar[j].b) {
                    match = true;
                    break;
                }
            }
            if (!match) {
                ugly = true;
                break;
            }
        }
        if (ugly) {
            System.out.println("ugly");
            return;
        }

        x = ar[5].b; y = ar[6].b; z = ar[7].b;
        if (x == y || x == z) {
            System.out.println("ugly");
            return;
        }

        if (!(ar[3].b == min || ar[3].b == max)) {
            System.out.println("ugly");
            return;
        }
        if (!(ar[4].b == min || ar[4].b == max)) {
            System.out.println("ugly");
            return;
        }
        if (ar[3].b == ar[4].b) {
            System.out.println("ugly");
            return;
        }

        System.out.println("respectable");
    }
}

